@implementation EZPhraseListViewController
- (void)viewDidLoad { [super viewDidLoad]; self.title = @"Ersatz"; self.navigationItem.rightBarButtonItem = [[UIBarButtonItem alloc] initWithBarButtonSystemItem:UIBarButtonSystemItemAdd target:self action:@selector(addPhrase)]; self.tableView = [[UITableView alloc] initWithFrame:self.view.bounds style:UITableViewStylePlain]; self.tableView.delegate = self; self.tableView.dataSource = self; [self.view addSubview:self.tableView]; CFArrayRef keys = CFPreferencesCopyKeyList(CFSTR("xyz.skitty.ersatz"), kCFPreferencesCurrentUser, kCFPreferencesAnyHost); if (keys) { _settings = (NSMutableDictionary *)CFBridgingRelease(CFPreferencesCopyMultiple(keys, CFSTR("xyz.skitty.ersatz"), kCFPreferencesCurrentUser, kCFPreferencesAnyHost)); CFRelease(keys); } else _settings = [[NSMutableDictionary alloc] initWithContentsOfFile:settingsPath]; if (!_settings) _settings = [NSMutableDictionary dictionary]; _settings[@"strings"] = [_settings[@"strings"] mutableCopy] ?: [NSMutableArray array]; [self sortSettings]; }
- (void)updateSettings { CFPreferencesSetAppValue(CFSTR("strings"), (__bridge CFPropertyListRef)_settings[@"strings"], CFSTR("xyz.skitty.ersatz")); [_settings writeToFile:settingsPath atomically:YES]; CFNotificationCenterPostNotification(CFNotificationCenterGetDarwinNotifyCenter(), CFSTR("xyz.skitty.ersatz.prefschanged"), NULL, NULL, true); }
- (void)sortSettings { _strings = [NSMutableDictionary dictionary]; _sortedStrings = [NSMutableDictionary dictionary]; for (NSDictionary *r in _settings[@"strings"]) { NSString *p = r[@"phrase"]; if (!p.length) continue; _strings[p] = r[@"replacement"] ?: @""; NSString *s = [[p substringToIndex:1] uppercaseString]; if (!_sortedStrings[s]) _sortedStrings[s] = [NSMutableArray array]; [_sortedStrings[s] addObject:p]; } for (NSString *s in _sortedStrings) [_sortedStrings[s] sortUsingSelector:@selector(localizedCaseInsensitiveCompare:)]; }
