- (void)addPhrase:(NSString *)p replacement:(NSString *)r caseSensitive:(BOOL)c wholeWord:(BOOL)w scope:(NSString *)s applications:(NSArray *)a { if (!_settings[@"shownPrompt"]) { UIAlertController *alert = [UIAlertController alertControllerWithTitle:@"Notice" message:@"Changes may require reopening apps or respringing." preferredStyle:UIAlertControllerStyleAlert]; [alert addAction:[UIAlertAction actionWithTitle:@"OK" style:UIAlertActionStyleDefault handler:nil]]; [self presentViewController:alert animated:YES completion:nil]; _settings[@"shownPrompt"] = @YES; } NSMutableDictionary *rule = [@{ @"phrase": p, @"replacement": r, @"caseSensitive": @(c), @"wholeWord": @(w), @"scope": s ?: @"all", @"applications": a ?: @[] } mutableCopy]; [_settings[@"strings"] addObject:rule]; [self updateSettings]; [self sortSettings]; [self.tableView reloadData]; }
- (void)editPhrase:(NSString *)old newPhrase:(NSString *)p replacement:(NSString *)r caseSensitive:(BOOL)c wholeWord:(BOOL)w scope:(NSString *)s applications:(NSArray *)a { for (NSUInteger i=0; i<[_settings[@"strings"] count]; i++) if ([_settings[@"strings"][i][@"phrase"] isEqualToString:old]) { _settings[@"strings"][i] = @{ @"phrase": p, @"replacement": r, @"caseSensitive": @(c), @"wholeWord": @(w), @"scope": s ?: @"all", @"applications": a ?: @[] }; break; } [self updateSettings]; [self sortSettings]; [self.tableView reloadData]; }
- (NSArray *)sections { return [[_sortedStrings allKeys] sortedArrayUsingSelector:@selector(localizedCaseInsensitiveCompare:)]; }
