- (void)tableView:(UITableView *)t didSelectRowAtIndexPath:(NSIndexPath *)i { NSString *p=_sortedStrings[[self sections][i.section]][i.row]; for (NSDictionary *r in _settings[@"strings"]) if ([r[@"phrase"] isEqualToString:p]) { EZEditPhraseViewController *c=[[EZEditPhraseViewController alloc] initWithDictionary:r]; c.parent=self; [self.navigationController pushViewController:c animated:YES]; break; } [t deselectRowAtIndexPath:i animated:YES]; }
